entries[331148] = { ["name"] = "Qual: Auge von Skoldus", ["text"] = "Animabonus\nSofort\nSkoldus hat das Ziel im Auge und ruft alle 40 Sek. schlundgebundene Sucher herbei, während das Ziel sich nicht im Kampf befindet. Diese Diener haben 5% mehr Gesundheit. Dieser Effekt ist stapelbar.\n\nQual des Turms" }
