entries[331641] = { ["name"] = "Konstellationskarte", ["text"] = "Animabonus\nSofort\nBei der Beschwörung eines Erhabenen beschwört Ihr 1 zusätzlichen Erhabenen." }
entries[331642] = { ["name"] = "Niuzao den Schwarzen Ochsen beschwören", ["text"] = "40 Meter Reichweite\nSofort 3 min Abklingzeit\nBeschwört für 25 Sek. ein Abbild von Niuzao, dem Schwarzen Ochsen. Niuzao greift Euer Primärziel an und stampft mehrmals auf, was allen Gegnern in der Nähe [ Verbessertes Niuzao den Schwarzen Ochsen beschwören : (200% der Angriffskraft) Schaden und zusätzlich 0% des kürzlich entfernten gestaffelten Schadens zufügt / Schaden zufügt.]\nWährend das Abbild aktiv ist, werden 25% des durch 'Staffeln' verzögerten Schadens stattdessen von Niuzao gestaffelt." }
entries[331643] = { ["name"] = "Xuen den Weißen Tiger beschwören", ["text"] = "40 Meter Reichweite\nSofort 2 min Abklingzeit\nBeschwört ein Abbild von Xuen, dem Weißen Tiger, das 25 Sek. lang bestehen bleibt. Xuen greift Euer Primärziel an und trifft 3 Gegner innerhalb von 10 Metern alle 1 Sek. mit Tigerblitzen, die (25.7% der Angriffskraft) Naturschaden verursachen." }
entries[331644] = { ["name"] = "Yu'lon die Jadeschlange beschwören", ["text"] = "40 Meter Reichweite\nSofort 3 min Abklingzeit\nBeschwört ein Abbild von Yu'lon, der Jadeschlange, das 25 Sek. lang bestehen bleibt. Yu'lon heilt Verbündete in der Nähe mit 'Himmlischer Atem' um (63% der Angriffskraft) Gesundheit." }
entries[331645] = { ["name"] = "Chi-Ji den Roten Kranich beschwören", ["text"] = "40 Meter Reichweite\nSofort\nBeschwört ein Abbild von Chi-Ji, das einen Nebelschwall auslöst, wenn Ihr 'Blackout-Tritt', 'Tritt der aufgehenden Sonne' oder 'Wirbelnder Kranichtritt' einsetzt, der bis zu 2 Verbündete um (0.1% der Zaubermacht) Gesundheit heilt und die Kosten und Zauberzeit Eures nächsten Einsatzes von 'Einhüllender Nebel' um 33% verringert. Diese Reduktion ist stapelbar.\n\nChi-Jis Präsenz macht Euch immun gegen bewegungseinschränkende Effekte." }
entries[331647] = { ["name"] = "Todesberührtes Gebräu", ["text"] = "Animabonus\nSofort\nSchaden von 'Berührung des Todes' erhöht den Effekt von 'Stärkendes Gebräu' um zusätzlich 5% der Maximalgesundheit, während Ihr in Torghast seid." }
