entries[331843] = { ["name"] = "Glaubensprüfung", ["text"] = "100 Meter Reichweite\nSofort\nFügt Eurem aktuellen Ziel einen Grundschaden von 400 Arkanschaden im Verlauf von 20 Treffern und 3 Sek. zu. Jeder nachfolgende Treffer während der Kanalisierung verursacht mehr Schaden.\n\nErzeugt 1 Energie pro Treffer." }
