entries[331997] = { ["name"] = "Animawoge", ["text"] = "Unbegrenzte Reichweite\nSofort\nBei Berührung platzt verdichtete Anima und fügt Spielercharakteren innerhalb von 5 Metern 1697115 Arkanschaden sowie zusätzlich 10 Sek. lang alle 1 Sek. 484890 Arkanschaden zu." }
