entries[332001] = { ["name"] = "Monströses Gemisch", ["text"] = "Animabonus\nSofort\n'Todesmantel' erfüllt Euch und Eure Diener mit monströser Macht, die den Schaden und das Angriffstempo 8 Sek. lang um 10% erhöht." }
entries[332002] = { ["name"] = "Phantasma verschlingen", ["text"] = "30 Meter Reichweite\nWirken in 1.5 sek.\nVerschlingt 10% des Phantasmas von Spielercharakteren innerhalb von 60 Metern und verursacht Schattenschaden. Diese Energie ermächtigt den Zaubernden und erhöht sein Tempo 6 Sek. lang um 50%." }
