entries[332254] = { ["name"] = "Schleuderansturm", ["text"] = "100 Meter Reichweite\nWirken in 1 sek.\nSchleudert seine Äxte auf ein Ziel, verursacht Schattenschaden und verlangsamt Gegner in einem Bereich. Stürmt dann auf seine Äxte zu und verursacht bei seiner Ankunft Schattenschaden in einem Bereich." }
