entries[332256] = { ["name"] = "Dämmerflatterardenmotte", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Diese Ardenmotten bevorzugen die dunklen und feuchten Wälder im Nordwesten des Ardenwalds, in denen Pilzkolonien ohne Unterlass erblühen.\"\nVerkäufer:\nAithlyn\nZone:\nArdenwald\nDie Wilde Jagd - Ehrfürchtig\nKosten:\n30.000" }
